describe('Payment Timeout Redirect to Error Page', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should redirect to error page when payment times out', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 408,
      body: { error: 'Payment timed out' }
    }).as('paymentTimeout');

    // Attempt to submit payment form
    cy.get('[data-testid="payment-form"]').should('be.visible');
    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="submit-button"]').click();

    // Wait for payment timeout response
    cy.wait('@paymentTimeout');

    // Verify redirection to error page
    cy.url().should('include', '/error');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Payment timed out');

    // Verify error page content
    cy.get('[data-testid="error-code"]').should('contain', '408');
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').click();

    // Verify retry button is still visible
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });

  it('should handle successful payment without timeout', () => {
    // Intercept successful payment API call
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 200,
      body: { success: true, transactionId: '123456789' }
    }).as('paymentSuccess');

    // Attempt to submit payment form
    cy.get('[data-testid="payment-form"]').should('be.visible');
    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="submit-button"]').click();

    // Wait for successful payment response
    cy.wait('@paymentSuccess');

    // Verify redirection to success page
    cy.url().should('include', '/success');
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Payment successful');

    // Verify success page content
    cy.get('[data-testid="transaction-id"]').should('contain', '123456789');
    cy.get('[data-testid="continue-to-checkout"]').should('be.visible');
  });
});
